$zipPath = Join-Path $PWD "auth-lib.zip"
$libPath = Join-Path $PWD "mobile\lib"
[IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String(($b64 -replace "\s","")))
if (Test-Path (Join-Path $libPath "main.dart")) { Copy-Item (Join-Path $libPath "main.dart") (Join-Path $libPath "main.dart.bak") -Force }
Expand-Archive -Path $zipPath -DestinationPath $libPath -Force
Remove-Item $zipPath -Force
Write-Host "SUCCESS: auth files installed into mobile\lib"
Write-Host "Run: cd mobile; flutter run -d emulator-5554"
